package main

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// writeTree lays out a tiny module: one hand-written and one generated file in
// context "knowledge", one platform file and one cmd file (not measured).
func writeTree(t *testing.T) string {
	t.Helper()
	root := t.TempDir()
	files := map[string]string{
		"go.mod":                            "module birge\n\ngo 1.27\n",
		"internal/domains/knowledge/svc.go": "// Package knowledge ...\npackage knowledge\n",
		"internal/domains/knowledge/api/api.gen.go": "// Package api provides primitives.\n//\n// Code generated by oapi-codegen DO NOT EDIT.\npackage api\n",
		"internal/platform/clock/clock.go":          "package clock\n",
		"cmd/birge/main.go":                         "package main\n",
	}
	for name, body := range files {
		p := filepath.Join(root, name)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o600); err != nil {
			t.Fatal(err)
		}
	}
	return root
}

// The api.gen.go header in writeTree puts "Code generated" after other
// comment lines, as oapi-codegen does; the checker must still see it.
const profile = `mode: atomic
birge/internal/domains/knowledge/svc.go:3.1,5.2 6 1
birge/internal/domains/knowledge/svc.go:6.1,8.2 4 0
birge/internal/domains/knowledge/svc.go:6.1,8.2 4 0
birge/internal/domains/knowledge/api/api.gen.go:3.1,9.2 90 0
birge/internal/platform/clock/clock.go:2.1,4.2 2 0
birge/internal/domains/knowledge/knowledgetest/fake.go:1.1,9.2 40 0
birge/internal/platform/clock/clock.go:2.1,4.2 2 3
birge/cmd/birge/main.go:2.1,4.2 50 0
`

func TestRun(t *testing.T) {
	tests := []struct {
		name     string
		floors   string // "" = no file
		update   bool
		wantCode int
		wantOut  []string
		wantFile []string
	}{
		{name: "at the floor", floors: "knowledge 60.0\nplatform 100.0\n", wantCode: 0,
			wantOut: []string{"knowledge          10     60.0     60.0  ok", "platform            2    100.0    100.0  ok"}},
		{name: "within tolerance", floors: "knowledge 60.4\nplatform 100\n", wantCode: 0},
		{name: "dropped", floors: "knowledge 60.6\nplatform 100\n", wantCode: 1, wantOut: []string{"FAIL 0.6 below the floor"}},
		{name: "context without floor", floors: "knowledge 60\n", wantCode: 1, wantOut: []string{"platform", "FAIL no floor"}},
		{name: "stale floor", floors: "knowledge 60\nplatform 100\ngone 10 # removed context\n", wantCode: 1, wantOut: []string{"gone", "FAIL no code measured"}},
		{name: "no floor file", wantCode: 2},
		{name: "bad floor file", floors: "knowledge sixty\n", wantCode: 2},
		{name: "update creates", update: true, wantCode: 0, wantFile: []string{"knowledge    60.0", "platform     100.0"}},
		{name: "update never lowers or hides a drop", floors: "knowledge 70\nplatform 100\ngone 5\n", update: true, wantCode: 1,
			wantFile: []string{"knowledge    70.0", "platform     100.0"}},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			root := writeTree(t)
			prof := filepath.Join(root, "cover.out")
			if err := os.WriteFile(prof, []byte(profile), 0o600); err != nil {
				t.Fatal(err)
			}
			floorFile := filepath.Join(root, "coverage-floor.txt")
			if tt.floors != "" {
				if err := os.WriteFile(floorFile, []byte(tt.floors), 0o600); err != nil {
					t.Fatal(err)
				}
			}
			var out strings.Builder
			code, err := run(root, prof, floorFile, 0.5, tt.update, &out)
			if code != tt.wantCode {
				t.Fatalf("code = %d (err %v), want %d\n%s", code, err, tt.wantCode, out.String())
			}
			for _, w := range tt.wantOut {
				if !strings.Contains(out.String(), w) {
					t.Errorf("output lacks %q:\n%s", w, out.String())
				}
			}
			if len(tt.wantFile) > 0 {
				data, err := os.ReadFile(floorFile)
				if err != nil {
					t.Fatal(err)
				}
				for _, w := range tt.wantFile {
					if !strings.Contains(string(data), w) {
						t.Errorf("floor file lacks %q:\n%s", w, data)
					}
				}
				if strings.Contains(string(data), "gone") {
					t.Errorf("floor of a removed context kept:\n%s", data)
				}
			}
		})
	}
}

func TestParseBlockErrors(t *testing.T) {
	for _, line := range []string{"no colon here", "a.go:1.1,2.2 x 1", "a.go:1.1,2.2 1 y", "a.go:1.1,2.2 1"} {
		if _, err := parseBlock(line); err == nil {
			t.Errorf("parseBlock(%q) accepted", line)
		}
	}
}

func TestIsTestSupport(t *testing.T) {
	tests := map[string]bool{
		"internal/domains/chat/chattest/fake.go": true,
		"internal/platform/testinfra/t.go":       false,
		"internal/domains/chat/service/s.go":     false,
	}
	for in, want := range tests {
		if got := isTestSupport(in); got != want {
			t.Errorf("isTestSupport(%q) = %v, want %v", in, got, want)
		}
	}
}

func TestContextOf(t *testing.T) {
	tests := map[string]string{
		"internal/domains/chat/service/s.go": "chat",
		"internal/domains/chat/doc.go":       "chat",
		"internal/platform/db/db.go":         "platform",
		"internal/wiring/w.go":               "",
		"cmd/birge/main.go":                  "",
	}
	for in, want := range tests {
		if got := contextOf(in); got != want {
			t.Errorf("contextOf(%q) = %q, want %q", in, got, want)
		}
	}
}
